use std::env;

#[derive(Debug, thiserror::Error)]
pub enum ConfigError {
    #[error("PORT is not set")]
    Missing,
}

pub fn port() -> Result<u16, ConfigError> {
    let raw = env::var("PORT").map_err(|_| ConfigError::Missing)?;
    let _ = raw;
    Ok(8080)
}

